package vn.svframe.lively.persistence;
import com.google.gson.*;import vn.svframe.lively.crime.CrimeEngine;import vn.svframe.lively.economy.EconomyEngine;import vn.svframe.lively.event.*;import vn.svframe.lively.faction.FactionEngine;import vn.svframe.lively.quest.QuestRuntime;import vn.svframe.lively.schedule.ScheduleEngine;import vn.svframe.lively.social.*;import vn.svframe.lively.world.SemanticStructureRegistry;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.time.Instant;import java.util.*;import java.util.concurrent.*;public final class SimulationStateStore implements AutoCloseable{private static final int SCHEMA=1;private static final long MAX_BYTES=128L*1024L*1024L;private final Path file,backup;private final Gson gson;private final ExecutorService io;public SimulationStateStore(Path file){this.file=file;backup=file.resolveSibling(file.getFileName()+".bak");gson=new GsonBuilder().enableComplexMapKeySerialization().registerTypeAdapter(Instant.class,(JsonSerializer<Instant>)(src,t,c)->c.serialize(src.toString())).registerTypeAdapter(Instant.class,(JsonDeserializer<Instant>)(j,t,c)->Instant.parse(j.getAsString())).create();io=Executors.newSingleThreadExecutor(r->{Thread x=new Thread(r,"Lively-Simulation-IO");x.setDaemon(true);return x;});}public Optional<Bundle>load(){Optional<Bundle>p=read(file);return p.isPresent()?p:read(backup);}public CompletableFuture<Void>saveAsync(Bundle b){String payload=gson.toJson(b),checksum=sha256(payload),envelope=gson.toJson(new Envelope(SCHEMA,checksum,payload));return CompletableFuture.runAsync(()->write(envelope),io);}private Optional<Bundle>read(Path path){if(!Files.isRegularFile(path))return Optional.empty();try{long size=Files.size(path);if(size<=0||size>MAX_BYTES)throw new IOException("invalid size");JsonObject root=JsonParser.parseString(Files.readString(path,StandardCharsets.UTF_8)).getAsJsonObject();if(root.get("schema").getAsInt()!=SCHEMA)throw new IOException("unsupported schema");String payload=root.get("payload").getAsString(),expected=root.get("checksum").getAsString();if(!MessageDigest.isEqual(expected.getBytes(StandardCharsets.US_ASCII),sha256(payload).getBytes(StandardCharsets.US_ASCII)))throw new IOException("checksum mismatch");return Optional.of(gson.fromJson(payload,Bundle.class));}catch(Exception e){return Optional.empty();}}private void write(String envelope){try{byte[]bytes=envelope.getBytes(StandardCharsets.UTF_8);if(bytes.length>MAX_BYTES)throw new IOException("state too large");Files.createDirectories(file.getParent());Path temp=file.resolveSibling(file.getFileName()+".tmp");Files.write(temp,bytes);if(Files.isRegularFile(file))Files.copy(file,backup,StandardCopyOption.REPLACE_EXISTING);try{Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(IOException ignored){Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}}catch(IOException e){throw new CompletionException(e);}}private static String sha256(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}@Override public void close(){io.shutdown();}private record Envelope(int schema,String checksum,String payload){}public record Bundle(SemanticStructureRegistry.Snapshot structures,SocialEngine.Snapshot social,Map<SocialEngine.Pair,RomanceEngine.Bond>romance,CrimeEngine.Snapshot crime,EconomyEngine.Snapshot economy,FactionEngine.Snapshot factions,QuestRuntime.Snapshot quests,ScheduleEngine.Snapshot schedules,Map<UUID,StoryArcEngine.Arc>storyArcs,Map<String,StorySeedEngine.Seed>storySeeds,WorldEventEngine.Snapshot events){}}
